    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { out.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    const two = s.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { out.push({ t: 'op', v: two }); i += 2; continue }
    if ('+-*/^()=<>:,'.includes(c)) { out.push({ t: 'op', v: c }); i++; continue }
    throw new Error('lex')
  }
  return out
}

// returns { ast, misplaced, refs: [addr...] } or null if grammar rejects
export function parse(body) {
  let toks
  try { toks = tokenize(body) } catch { return null }
  let p = 0
  const refs = []
  let misplaced = false
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw new Error('parse') }
  const addRef = (w) => { const a = parseAddr(w); if (a) refs.push(a); return a }

  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) fail()
    if (t.t === 'num') { p++; return { n: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return { n: 'paren', e }
    }
    if (t.t === 'word') {
      p++
      const up = t.v.toUpperCase()
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { n: 'call', name: up, args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.t !== 'word') fail()
        p++
        if (isOp('(')) fail()
        const a = addRef(t.v), b = addRef(t2.v)
        if (a && b) {
          for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
            for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) refs.push({ col: c, row: r })
          // endpoints already added; harmless duplicates
        }
        return { n: 'range', a, b }
      }
      if (up === 'TRUE') return { n: 'bool', v: true }
      if (up === 'FALSE') return { n: 'bool', v: false }
      return { n: 'ref', a: addRef(t.v) }
    }
    fail()
  }
  let ast
  try {
    ast = cmp()
    if (p < toks.length) fail()
  } catch { return null }
  // misplaced range check
  const walk = (n, argPos) => {
    switch (n.n) {
      case 'range': if (!argPos) misplaced = true; break
      case 'bin': walk(n.l, false); walk(n.r, false); break
      case 'un': case 'paren': walk(n.e, false); break
      case 'call': n.args.forEach((a) => walk(a, true)); break
    }
  }
  walk(ast, false)
  return { ast, misplaced, refs }
}

export function rank(v) { return v.k === 'num' ? 0 : v.k === 'text' ? 1 : 2 }
function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const num = (v) => ({ k: 'num', v })
const fin = (x) => (Number.isFinite(x) ? num(x) : ERR('#DIV/0!'))
function toNum(v) {
  if (v.k === 'num') return v
  if (v.k === 'bool') return num(v.v ? 1 : 0)
  return ERR('#VALUE!')
}

export function evaluate(ast, getCell) {
  function ev(n) {
    switch (n.n) {
      case 'num': return num(n.v)
      case 'bool': return { k: 'bool', v: n.v }
      case 'paren': return ev(n.e)
      case 'ref': return n.a ? getCell(n.a) : ERR('#REF!')
      case 'range': return ERR('#ERR!')
      case 'un': {
        const v = ev(n.e)
        if (v.k === 'err') return v
        const x = toNum(v)
        if (x.k === 'err') return x
        return n.op === '-' ? num(-x.v) : x
      }
      case 'bin': {
        const l = ev(n.l)
        if (l.k === 'err') return l
        const r = ev(n.r)
        if (r.k === 'err') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          let d
          const rl = rank(l), rr = rank(r)
          if (rl !== rr) d = rl - rr
          else if (l.k === 'num') d = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
          else if (l.k === 'text') d = cpCompare(l.v, r.v)
          else d = Number(l.v) - Number(r.v)
          const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
          return { k: 'bool', v: res }
        }
        const a = toNum(l)
        if (a.k === 'err') return a
        const b = toNum(r)
        if (b.k === 'err') return b
        switch (n.op) {
          case '+': return fin(a.v + b.v)
          case '-': return fin(a.v - b.v)
          case '*': return fin(a.v * b.v)
          case '/': return b.v === 0 ? ERR('#DIV/0!') : fin(a.v / b.v)
          case '^': return fin(Math.pow(a.v, b.v))
        }
        return ERR('#ERR!')
      }
      case 'call': return call(n)
    }
    return ERR('#ERR!')
  }
  function call(n) {
    const name = n.name, args = n.args
    if (!FUNCS.has(name)) return ERR('#NAME?')
    if (name === 'IF') {
      if (args.length !== 3 || args.some((a) => a.n === 'range')) return ERR('#ERR!')
      const c = ev(args[0])
      if (c.k === 'err') return c
      if (c.k === 'text') return ERR('#VALUE!')
      const truth = c.k === 'bool' ? c.v : c.v !== 0
      return ev(truth ? args[1] : args[2])
    }
    if (name === 'ABS') {
      if (args.length !== 1 || args[0].n === 'range') return ERR('#ERR!')
      const v = ev(args[0])
      if (v.k === 'err') return v
      const x = toNum(v)
      return x.k === 'err' ? x : num(Math.abs(x.v))
    }
    if (args.length < 1) return ERR('#ERR!')
    const vals = []
    for (const a of args) {
      if (a.n === 'range') {
        if (!a.a || !a.b) return ERR('#REF!')
        for (let c = Math.min(a.a.col, a.b.col); c <= Math.max(a.a.col, a.b.col); c++)
          for (let r = Math.min(a.a.row, a.b.row); r <= Math.max(a.a.row, a.b.row); r++) {
            const v = getCell({ col: c, row: r })
            if (v.k === 'err') return v
            vals.push(v)
          }
      } else {
        const v = ev(a)
        if (v.k === 'err') return v
        vals.push(v)
      }
    }
    if (name === 'COUNT') return num(vals.filter((v) => v.k === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.k === 'err') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
      case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
      case 'MIN': return num(nums.reduce((s, x) => (x < s ? x : s), Infinity))
      case 'MAX': return num(nums.reduce((s, x) => (x > s ? x : s), -Infinity))
    }
    return ERR('#ERR!')
  }
  return ev(ast)
}
