import { readFileSync } from 'node:fs'
import { ERRS, parse, parseAddr, key, evaluate } from './formula.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') continue
  const m = /^[^ \t]*/.exec(line)
  const addrText = m[0]
  const rest = line.slice(addrText.length).replace(/^[ \t]+/, '')
  const a = parseAddr(addrText)
  if (!a) fatal(`error: line ${i + 1}: invalid cell address ${addrText}`)
  const k = key(a)
  if (cells.has(k)) fatal(`error: line ${i + 1}: cell ${k} is declared twice`)
  cells.set(k, { a, content: rest })
}
function fatal(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

for (const c of cells.values()) {
  const s = c.content
  if (s[0] === '=') {
    c.formula = parse(s.slice(1))
  } else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) c.lit = { k: 'num', v: Number(s) }
  else if (s === '') c.lit = { k: 'num', v: 0 }
  else if (ERRS.includes(s)) c.lit = { k: 'err', v: s }
  else c.lit = { k: 'text', v: s }
}

const sorted = [...cells.values()].sort((x, y) => x.a.col - y.a.col || x.a.row - y.a.row)
const out = []

if (mode === 'deps') {
  for (const c of sorted) {
    let s = key(c.a) + ':'
    if (c.formula) {
      const seen = new Map()
      for (const r of c.formula.refs) seen.set(r.col * 1000 + r.row, r)
      const list = [...seen.values()].sort((x, y) => x.col - y.col || x.row - y.row)
      for (const r of list) s += ' ' + key(r)
    }
    out.push(s)
  }
} else {
  const memo = new Map()
  const busy = new Set()
  const getCell = (a) => {
    const k = key(a)
    const c = cells.get(k)
    if (!c) return { k: 'num', v: 0 }
    if (c.lit) return c.lit
    if (memo.has(k)) return memo.get(k)
    if (busy.has(k)) return { k: 'err', v: '#CYCLE!' }
    busy.add(k)
    let v
    if (!c.formula || c.formula.misplaced) v = { k: 'err', v: '#ERR!' }
    else v = evaluate(c.formula.ast, getCell)
    busy.delete(k)
    memo.set(k, v)
    return v
  }
  for (const c of sorted) {
    const v = getCell(c.a)
    let t
    if (v.k === 'num') t = String(Number(v.v.toPrecision(10)))
    else if (v.k === 'bool') t = v.v ? 'TRUE' : 'FALSE'
    else t = v.v
    out.push(`${key(c.a)}=${t}`)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
